import { createContext } from 'react';

import type { TimeframeSelectorBaseProps } from '../TimeframeSelector.js';

/** @internal */
export interface _InternalTimeframeSelectorContextProps {
  /** The ISODatetime string of the earliest datetime that can be configured. */
  min?: string;
  /** The ISODatetime string of the latest datetime that can be configured. */
  max?: string;
  /** Whether the element is in an error state. */
  hasError?: boolean;
  /** Whether the element is required. */
  required?: boolean;
  /** Whether the element is readOnly. */
  readOnly?: boolean;
  /** The precision of the time shown in the display value. */
  precision?: TimeframeSelectorBaseProps['precision'];
}

/**
 * Timeframe selector context, used to access the (input) value and onChange callback in other components.
 * @internal
 */
export const _InternalTimeframeSelectorContext: React.Context<_InternalTimeframeSelectorContextProps> =
  createContext<_InternalTimeframeSelectorContextProps>({
    min: '',
    max: '',
    hasError: false,
    required: false,
    readOnly: false,
    precision: 'minutes',
  });
